WITH gated AS (SELECT model FROM llm_gateway.usage_log WHERE {{ time_filter('timestamp') }} AND model != '' GROUP BY model HAVING count() >= 100), sessions AS (SELECT model, session_id, count() AS msgs FROM llm_gateway.request_log WHERE {{ time_filter('timestamp') }} AND session_id != '' AND model != '' AND coalesce(nullIf(key_id,''), nullIf(api_key_id,''), 'unknown') IN ({{ gf_str_multi('api_key') }}) GROUP BY model, session_id), depth AS (SELECT model, round(avg(msgs), 2) AS value FROM sessions WHERE model IN ({{ gf_str_multi('model') }}) AND model IN (SELECT model FROM gated) GROUP BY model) SELECT s.model AS name_str, s.value AS value FROM depth AS s ORDER BY value DESC LIMIT 20
